create type public.app_role as enum ('admin','student','graduated_student','faculty');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create function public.has_role(_user_id uuid, _role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke all on function public.has_role(uuid,public.app_role) from public,anon; grant execute on function public.has_role(uuid,public.app_role) to authenticated,service_role;
create policy roles_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', username text unique, email text not null default '', student_no text, department text not null default 'Computer Science', status text not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select,update on public.profiles to authenticated; grant all on public.profiles to service_role;
alter table public.profiles enable row level security;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.has_role(auth.uid(),'admin'));
create policy profiles_admin_update on public.profiles for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create function public.validate_profile() returns trigger language plpgsql set search_path=public as $$ begin if new.status not in ('pending','approved') then raise exception 'Invalid status'; end if; if new.username is not null then new.username=lower(trim(new.username)); end if; if TG_OP='UPDATE' then new.updated_at=now(); end if; return new; end $$;
create trigger profile_validation before insert or update on public.profiles for each row execute function public.validate_profile();
create function public.touch_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
create trigger roles_updated before update on public.user_roles for each row execute function public.touch_updated_at();
create function public.create_account_profile() returns trigger language plpgsql security definer set search_path=public as $$ declare account_role public.app_role; begin account_role=case new.raw_user_meta_data->>'role' when 'Faculty' then 'faculty'::public.app_role when 'Graduated Student' then 'graduated_student'::public.app_role else 'student'::public.app_role end; insert into public.profiles(id,full_name,email,student_no) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.email,''),new.raw_user_meta_data->>'student_no'); insert into public.user_roles(user_id,role) values(new.id,account_role); return new; end $$;
revoke all on function public.create_account_profile() from public,anon,authenticated;
create trigger on_account_created after insert on auth.users for each row execute function public.create_account_profile();